{
  "schema": "ai7.readers-report.unit-result/1",
  "unitOrdinal": 7,
  "passages": [
    {
      "kind": "strength",
      "note": "书房独坐一段以曾侯乙尊盘黑白照片为核心意象，写它是曾本之“个人生活中的唯一饰物”，又以长江汉水交汇暗流比拟胸中涌动，含蓄塑造人物内心。",
      "blockOrdinals": [2]
    },
    {
      "kind": "strength",
      "note": "“比女人的烫发还要复杂的透空蟠虺纹饰”等比喻带个人化口吻，把专业器物描写化为可感形象。",
      "blockOrdinals": [2]
    },
    {
      "kind": "problem",
      "note": "此处以女性外貌特征作比形容纹饰复杂度，性别化修辞与前后典雅的器物笔调并置，语体偶有落差，易引争议。",
      "blockOrdinals": [2]
    },
    {
      "kind": "strength",
      "note": "家庭场景中安静夺放大镜抱怨、楚楚前扑挂脖、曾本之捂嘴笑谈“出气筒”“刮台风”，人物声音各不相同，生活气息与幽默感具体。",
      "blockOrdinals": [4, 5, 7]
    },
    {
      "kind": "strength",
      "note": "楚楚“管青铜的就不要管丝绸，管甲骨文的就不要管漆器”的童言，以孩子口吻点出学科分工，兼具俏皮与反讽意味。",
      "blockOrdinals": [8]
    },
    {
      "kind": "strength",
      "note": "郑雄“嘴角咧两下，又让眉梢扬两下”的细节动作，写出其人在长者面前既不敢笑又不能不失笑的分寸与世故。",
      "blockOrdinals": [18]
    },
    {
      "kind": "strength",
      "note": "围绕楚学研究展开：曾本之责郑雄只开会不研究，郑雄答“楚学这一块就那么多东西”、门下弟子共识是反击不相信楚学真理的谬论，呈现学术与仕途、守护与争论的张力。",
      "blockOrdinals": [15, 16]
    },
    {
      "kind": "strength",
      "note": "借郑雄“占住这个位置，才发现这个位置有多么重要”，把学术立场与行政职位的现实关系点出，带社会与体制语境的观察。",
      "blockOrdinals": [18]
    },
    {
      "kind": "strength",
      "note": "九鼎七簋不合八簋之制、一九六五年天兽御尊孤单埋于荒野等具体考古疑点被提出，显示文本嵌入真实学术议题的知识背景。",
      "blockOrdinals": [17]
    },
    {
      "kind": "strength",
      "note": "郑雄转述副省长超越常务副省长升为省长、众人捧场的会议，点染官场生态，与家中学者话题形成对照。",
      "blockOrdinals": [14]
    },
    {
      "kind": "strength",
      "note": "场景在同一屋檐下自然推移：书房独坐、家人进门、门铃再响、郑雄回家，“郑雄一进门，家里的气氛就有了微妙变化”完成气氛转折。",
      "blockOrdinals": [2, 10, 12]
    },
    {
      "kind": "strength",
      "note": "曾本之“大约是内心有了别的想法”而对照片细察，呼应上一单元他决定暂不向郑雄提及甲骨文信件、约见马跃之的心事，前后线索相连。",
      "blockOrdinals": [1, 2]
    },
    {
      "kind": "strength",
      "note": "“书房的门没有关，但曾本之还是没有听见门铃声”一句为安静来夺放大镜作因，细节铺垫使家常插曲衔接顺畅。",
      "blockOrdinals": [3, 4]
    },
    {
      "kind": "strength",
      "note": "全单元以对话为主体推进：问开会、议研究、举考古疑点、答以位置之重要，问答递进把冲突层层展开。",
      "blockOrdinals": [13, 15, 16, 17, 18]
    },
    {
      "kind": "strength",
      "note": "人物对话口语鲜活：“耍嘴皮子”“大树底下好乘凉”“只有狡辩的才能大有长进”等俗语、成语化用贴切自然。",
      "blockOrdinals": [15, 16]
    },
    {
      "kind": "strength",
      "note": "“防患于未然”“登峰造极”“著书立说”等书面语与家常调侃语混用，形成学者家庭特有的语体层次。",
      "blockOrdinals": [16, 18]
    },
    {
      "kind": "strength",
      "note": "“只有你这小东西，能将外公的魂从那些破铜烂铁上找回来”等句以口语见亲昵，兼含对老学者痴迷器物的调侃。",
      "blockOrdinals": [6]
    },
    {
      "kind": "problem",
      "note": "九鼎七簋、天兽御尊、透空蟠虺纹饰等专门术语在本单元密集出现，对缺乏考古背景的读者构成一定阅读门槛。",
      "blockOrdinals": [2, 17]
    },
    {
      "kind": "problem",
      "note": "本单元推进主要靠对话与信息释放，官场见闻、学术分歧、藏书照片之辨多以闲谈点染，缺少外部行动与正面冲突，情节进展偏慢。",
      "blockOrdinals": [13, 14, 15, 16, 17, 18]
    },
    {
      "kind": "strength",
      "note": "青铜重器、出土之谜等悬念性话题与家庭温情场面交替，楚楚插科打诨、夺放大镜等轻喜段落调节节奏，可读性强，便于普通读者进入。",
      "blockOrdinals": [2, 4, 5, 7]
    }
  ]
}
